{
  "id": 25,
  "knowledge": "Session Anonymity Levels",
  "description": "How anonymous a session appears.",
  "definition": "Values: High, Medium, Low."
}

{
  "id": 4,
  "knowledge": "Anonymity Cost Index",
  "description": "Traceability score per anonymity level.",
  "definition": "ACI = \\frac{\\text{traceability\\_cost}}{\\text{anonymity\\_score}}"
}

{
  "id": 22,
  "knowledge": "Buyer Authentication Levels",
  "description": "Levels of login verification for buyers.",
  "definition": "Values: Advanced, Basic. Label descriptions: - Advanced: Account protected by multi factor authentication or hardware-backed credentials, offering high assurance. - Basic: Account relies on single factor authentication such as a password, with no secondary verification."
}

{
  "id": 21,
  "knowledge": "Vendor Access Levels",
  "description": "Privileges granted to vendor accounts.",
  "definition": "Values: Full, Partial. Label descriptions: - Full: Vendor can create listings, modify inventory, withdraw funds, and communicate without restriction. - Partial: Vendor functionality is limited, typically view only or blocked from withdrawals until verification is complete."
}

{
  "id": 26,
  "knowledge": "Alert Severity Levels",
  "description": "Importance level of alerts.",
  "definition": "Values: Critical, High, Medium, Low."
}

{
  "id": 12,
  "knowledge": "Advanced Verification Tier",
  "description": "Vendors with strong identity validation.",
  "definition": "Vendors who have completed multi factor or document backed identity validation are classified as Advanced tier."
}

{
  "id": 14,
  "knowledge": "Premium Authentication",
  "description": "Sessions with multi-factor authentication or 2FA.",
  "definition": "Sessions secured by two factor or multi factor authentication are considered to have Premium authentication."
}

{
  "id": 17,
  "knowledge": "Secure Platform",
  "description": "Platforms with low vulnerabilities and high protection count.",
  "definition": "A platform with fewer than ten unresolved security vulnerabilities and more than fifteen active protection measures qualifies as Secure."
}

{
  "id": 0,
  "knowledge": "Marketplace Risk Score (MRS)",
  "description": "Evaluates the overall risk of a platform.",
  "definition": "MRS = \\frac{0.4 \\times \\text{vuln\\_count} + 0.3 \\times \\text{event\\_count} + 0.3 \\times \\text{reputation\\_score}}{100}"
}

{
  "id": 7,
  "knowledge": "Threat Handling Rate",
  "description": "How efficiently threats are managed over time.",
  "definition": "THR = \\frac{\\text{threats\\_handled}}{\\text{total\\_hours}}"
}

{
  "id": 3,
  "knowledge": "Data Protection Efficiency",
  "description": "Efficiency of data protection per vulnerability.",
  "definition": "DPE = \\frac{\\text{protection\\_measures}}{\\text{vulnerability\\_instances}}"
}

{
  "id": 8,
  "knowledge": "Suspicion Signal Density",
  "description": "Keyword hits per message volume in communication.",
  "definition": "SSD = \\frac{\\text{keyword\\_matches}}{\\text{total\\_messages}}"
}

{
  "id": 2,
  "knowledge": "Compliance Efficiency Index (CEI)",
  "description": "Represents vendor's compliance performance.",
  "definition": "CEI = \\frac{\\text{compliance\\_score}}{\\text{violation\\_count}}"
}

{
  "id": 1,
  "knowledge": "Transaction Velocity Rate",
  "description": "Measures transaction completion speed.",
  "definition": "TVR = \\frac{\\text{total\\_transactions}}{\\text{active\\_time\\_in\\_hours}}"
}

{
  "id": 9,
  "knowledge": "Wallet Turnover Rate",
  "description": "Turnover of funds in a crypto wallet.",
  "definition": "WTR = \\frac{\\text{value\\_moved}}{\\text{wallet\\_age\\_in\\_days}}"
}

{
  "id": 10,
  "knowledge": "High Risk Vendor",
  "description": "A vendor flagged with active investigation or high law-enforcement interest.",
  "definition": "A vendor is deemed High Risk if there is an active regulatory or law-enforcement investigation in progress, or formal records indicate high interest from authorities."
}

{
  "id": 11,
  "knowledge": "Cross-Border Transaction",
  "description": "Indicates the shipment moves across national boundaries.",
  "definition": "Any transaction where the shipment passes from one country to another, triggering customs or import controls."
}

{
  "id": 5,
  "knowledge": "Buyer Risk Dollar Ratio",
  "description": "Risk per dollar spent by a buyer.",
  "definition": "BRDR = \\frac{\\text{risk\\_score}}{\\text{total\\_spending\\_usd}}"
}

{
  "id": 6,
  "knowledge": "Platform Liquidity Rate",
  "description": "Liquidity as a function of transaction flow and price.",
  "definition": "PLR = \\frac{\\text{successful\\_txns} \\times \\text{average\\_price}}{\\text{days\\_active}}"
}

{
  "id": 16,
  "knowledge": "Suspicious Buyer",
  "description": "Buyers with low behavior consistency or high risk ratio.",
  "definition": "A buyer is labeled Suspicious when their behavioural consistency score is low and their risk per dollar metric is notably high."
}

{
  "id": 19,
  "knowledge": "Tier-3 Escalation Case",
  "description": "Alert cases escalated to the highest priority tier.",
  "definition": "Alert cases escalated to Tier-3 represent the highest priority and warrant immediate incident response action."
}

{
  "id": 20,
  "knowledge": "Platform Operational Status",
  "description": "Indicates current state of platform functionality.",
  "definition": "Values: Active, Closed, Suspended, Under Investigation. Label descriptions: - Active: The marketplace is online, accepting new listings and processing transactions normally.- Closed: Operators have permanently shut down the marketplace; no further log ins or transactions are possible. - Suspended: The marketplace is temporarily offline, often due to policy violations or maintenance, and may return to service. - Under Investigation: Law enforcement or compliance review is in progress; user activity is restricted or frozen."
}

{
  "id": 23,
  "knowledge": "Product Categories",
  "description": "The general type of products listed.",
  "definition": "Values: Data, Digital, Physical, Service. Label descriptions: - Data: Digital information assets such as credential dumps, personal records, or proprietary databases. - Digital: Intangible goods like software licenses, media subscriptions, or downloadable files. - Physical: Tangible merchandise shipped to the buyer, including hardware devices or printed documents. - Service: Intangible labor or expertise, e.g., penetration testing, content creation, or laundering assistance."
}

{
  "id": 24,
  "knowledge": "Shipping Route Complexity",
  "description": "Describes the complexity of delivery routes.",
  "definition": "Values: Simple, Medium, Complex."
}

{
  "id": 27,
  "knowledge": "Escrow Usage States",
  "description": "Whether escrow was used in a transaction.",
  "definition": "Values: Yes, No.\nLabel descriptions:\n- Yes: Funds were held in escrow pending delivery confirmation or dispute resolution, reducing counterparty risk.\n- No: Payment was released directly without escrow protection, increasing the chance of fraud."
}

{
  "id": 28,
  "knowledge": "Language Patterns",
  "description": "Communication grammar detected in messages.",
  "definition": "Values: Consistent, Suspicious, Variable.\nLabel descriptions:\n- Consistent: Uniform grammar, vocabulary, and tone across messages, suggesting a single genuine author.\n- Suspicious: Irregular phrasing, sudden language switches, or machine translated text indicating possible deception.\n- Variable: Mixed linguistic styles from multiple senders or intentionally altered patterns to hinder profiling."
}

{
  "id": 29,
  "knowledge": "Spend Pattern Categories",
  "description": "Buyer spending trends.",
  "definition": "Values: High, Low, Medium, Variable.\nLabel descriptions:\n- High: Frequent, high value purchases indicative of heavy marketplace engagement.\n- Low: Infrequent, low value purchases typical of casual or opportunistic buyers.\n- Medium: Steady purchasing cadence with moderate transaction amounts.\n- Variable: Irregular bursts of spending with no predictable pattern."
}
